struct Block {
    let first: Int, last: Int, labels: [String]
    var successors: [Int] = [], predecessors: [Int] = []
}
struct NaturalLoop {
    let header: Int, latches: [Int], blocks: Set<Int>, exits: Set<Int>, outside: Set<Int>;
    var depth = 0
}
final class Graph {
    let instructions: [Instruction]
    var blocks: [Block] = [], owners: [Int] = [], positions: [Int] = [], reachable: Set<Int> = [], postorder: [Int] = [], order: [Int] = [], dominators: [Set<Int>] = [], idom: [Int?] = [], loops: [NaturalLoop] = [], depths: [Int] = []
    init(_ function: Function) {
        instructions = function.instructions;
        var labels: [Int: [String]] = [:], leaders: Set<Int> = [0], index = 0
        for (lineIndex, line) in function.code.enumerated() {
            switch line {
                case .label(let label): labels[index, default: []].append(label);
                leaders.insert(index);
                case .instruction(let instruction): positions.append(lineIndex);
                index += 1;
                if ["goto", "if", "return"].contains(instruction.kind) && index < instructions.count {
                    leaders.insert(index)
                }
            }
        }
        let starts = leaders.sorted();
        owners = Array(repeating: 0, count: instructions.count)
        for (i, first) in starts.enumerated() {
            let last = i + 1 < starts.count ? starts[i + 1] - 1 : instructions.count - 1;
            blocks.append(Block(first: first, last: last, labels: labels[first] ?? []));
            for j in first...last {
                owners[j] = i
            }
        }
        var labelBlocks: [String: Int] = [:];
        for (i, block) in blocks.enumerated() {
            for label in block.labels {
                labelBlocks[label] = i
            }
        }
        for i in blocks.indices {
            let instruction = instructions[blocks[i].last]
            if instruction.kind == "goto" {
                blocks[i].successors = [labelBlocks[instruction.target]!]
            }
            else if instruction.kind == "if" {
                blocks[i].successors = [i + 1];
                let target = labelBlocks[instruction.target]!;
                if target != i + 1 {
                    blocks[i].successors.append(target)
                }
            }
            else if instruction.kind != "return" {
                blocks[i].successors = [i + 1]
            }
        }
        for i in blocks.indices {
            for j in blocks[i].successors {
                blocks[j].predecessors.append(i)
            }
        };
        visit(0);
        order = Array(postorder.reversed())
        dominators = blocks.indices.map {
            $0 == 0 ? [0] : reachable
        };
        idom = Array(repeating: nil, count: blocks.count)
        while true {
            var changed = false
            for b in order.dropFirst() {
                let predecessors = blocks[b].predecessors.filter {
                    reachable.contains($0)
                };
                var set = reachable;
                for p in predecessors {
                    set.formIntersection(dominators[p])
                };
                set.insert(b);
                if set != dominators[b] {
                    dominators[b] = set;
                    changed = true
                }
            };
            if !changed {
                break
            }
        }
        for b in order.dropFirst() {
            idom[b] = dominators[b].filter {
                $0 != b
            }.max {
                dominators[$0].count == dominators[$1].count ? $0 > $1 : dominators[$0].count < dominators[$1].count
            }
        }
        for h in reachable.sorted() {
            let latches = reachable.filter {
                blocks[$0].successors.contains(h) && dominators[$0].contains(h)
            }.sorted();
            if latches.isEmpty {
                continue
            }
            var members: Set<Int> = [h], pending = latches
            while let b = pending.popLast() {
                if b == h || !members.insert(b).inserted {
                    continue
                };
                pending += blocks[b].predecessors.filter {
                    reachable.contains($0)
                }
            }
            var exits: Set<Int> = [], outside: Set<Int> = []
            for b in members {
                if instructions[blocks[b].last].kind == "return" {
                    exits.insert(b)
                };
                for s in blocks[b].successors where !members.contains(s) {
                    exits.insert(b);
                    outside.insert(s)
                }
            }
            loops.append(NaturalLoop(header: h, latches: latches, blocks: members, exits: exits, outside: outside))
        }
        depths = blocks.indices.map {
            b in loops.filter {
                $0.blocks.contains(b)
            }.count
        }
        for i in loops.indices {
            let header = loops[i].header;
            loops[i].depth = loops.filter {
                $0.blocks.contains(header)
            }.count
        }
    }
    func visit(_ b: Int) {
        reachable.insert(b);
        for s in blocks[b].successors where !reachable.contains(s) {
            visit(s)
        };
        postorder.append(b)
    }
}

struct DefinitionKey: Hashable {
    let variable: String, number: Int
}
struct CopyKey: Hashable {
    let destination: String, source: String
}
struct FlowSets<Element: Hashable> {
    var input: [Set<Element>], output: [Set<Element>], iterations = 0
}
enum Transfer {
    static func definitions(_ set: Set<DefinitionKey>, _ instruction: Instruction, _ number: Int) -> Set<DefinitionKey> {
        guard let x = instruction.destination else {
            return set
        };
        return Set(set.filter {
            $0.variable != x
        }).union([DefinitionKey(variable: x, number: number)])
    }
    static func live(_ set: Set<String>, _ instruction: Instruction) -> Set<String> {
        var result = set;
        if let x = instruction.destination {
            result.remove(x)
        };
        result.formUnion(instruction.used);
        return result
    }
    static func expressions(_ original: Set<TacExpression>, _ instruction: Instruction) -> Set<TacExpression> {
        var set = original;
        if let expression = instruction.expression {
            set.insert(expression)
        }
        if instruction.kind == "store" {
            set = Set(set.filter {
                $0.kind != "load" || $0.operation != instruction.array
            })
        }
        if instruction.kind == "call" {
            set = Set(set.filter {
                $0.kind != "load"
            })
        }
        if let x = instruction.destination {
            set = Set(set.filter {
                !$0.uses(x)
            })
        };
        return set
    }
    static func copies(_ original: Set<CopyKey>, _ instruction: Instruction) -> Set<CopyKey> {
        var set = original
        if let x = instruction.destination {
            set = Set(set.filter {
                $0.destination != x && $0.source != x
            });
            if instruction.kind == "copy", let y = instruction.a?.variable, y != x {
                set.insert(CopyKey(destination: x, source: y))
            }
        };
        return set
    }
}
final class Analysis {
    var definitions: FlowSets<DefinitionKey>, live: FlowSets<String>, expressions: FlowSets<TacExpression>, copies: FlowSets<CopyKey>
    var beforeDefinitions: [Set<DefinitionKey>], beforeExpressions: [Set<TacExpression>], beforeCopies: [Set<CopyKey>], beforeLive: [Set<String>], afterLive: [Set<String>]
    init(_ function: Function, _ graph: Graph) {
        let count = graph.blocks.count, n = graph.instructions.count, reachableInstructions = graph.instructions.indices.filter {
            graph.reachable.contains(graph.owners[$0])
        }, universe = Set(reachableInstructions.compactMap {
            graph.instructions[$0].expression
        })
        let copyUniverse = Set(reachableInstructions.compactMap {
            i -> CopyKey? in let instruction = graph.instructions[i];
            if instruction.kind == "copy", let x = instruction.destination, let y = instruction.a?.variable, x != y {
                return CopyKey(destination: x, source: y)
            };
            return nil
        })
        definitions = FlowSets(input: Array(repeating: [], count: count), output: Array(repeating: [], count: count));
        live = FlowSets(input: Array(repeating: [], count: count), output: Array(repeating: [], count: count))
        expressions = FlowSets(input: Array(repeating: [], count: count), output: Array(repeating: universe, count: count));
        copies = FlowSets(input: Array(repeating: [], count: count), output: Array(repeating: copyUniverse, count: count))
        beforeDefinitions = Array(repeating: [], count: n);
        beforeExpressions = Array(repeating: [], count: n);
        beforeCopies = Array(repeating: [], count: n);
        beforeLive = Array(repeating: [], count: n);
        afterLive = Array(repeating: [], count: n)
        while true {
            definitions.iterations += 1;
            var changed = false
            for b in graph.order {
                var set: Set<DefinitionKey> = b == 0 ? Set(function.parameters.map {
                    DefinitionKey(variable: $0, number: 0)
                }) : []
                for p in graph.blocks[b].predecessors where graph.reachable.contains(p) {
                    set.formUnion(definitions.output[p])
                };
                definitions.input[b] = set
                for i in graph.blocks[b].first...graph.blocks[b].last {
                    set = Transfer.definitions(set, graph.instructions[i], i + 1)
                };
                if definitions.output[b] != set {
                    changed = true
                };
                definitions.output[b] = set
            };
            if !changed {
                break
            }
        }
        while true {
            live.iterations += 1;
            var changed = false
            for b in graph.postorder {
                var set: Set<String> = [];
                for s in graph.blocks[b].successors {
                    set.formUnion(live.input[s])
                };
                live.output[b] = set
                for i in (graph.blocks[b].first...graph.blocks[b].last).reversed() {
                    set = Transfer.live(set, graph.instructions[i])
                };
                if set != live.input[b] {
                    changed = true
                };
                live.input[b] = set
            };
            if !changed {
                break
            }
        }
        expressions = Self.available(expressions, graph, universe, Transfer.expressions)
        copies = Self.available(copies, graph, copyUniverse, Transfer.copies)
        for b in graph.reachable {
            var d = definitions.input[b], e = expressions.input[b], c = copies.input[b]
            for i in graph.blocks[b].first...graph.blocks[b].last {
                beforeDefinitions[i] = d;
                beforeExpressions[i] = e;
                beforeCopies[i] = c;
                d = Transfer.definitions(d, graph.instructions[i], i + 1);
                e = Transfer.expressions(e, graph.instructions[i]);
                c = Transfer.copies(c, graph.instructions[i])
            }
            var l = live.output[b]
            for i in (graph.blocks[b].first...graph.blocks[b].last).reversed() {
                afterLive[i] = l;
                l = Transfer.live(l, graph.instructions[i]);
                beforeLive[i] = l
            }
        }
    }
    static func available<T: Hashable>(_ original: FlowSets<T>, _ graph: Graph, _ universe: Set<T>, _ transfer: (Set<T>, Instruction) -> Set<T>) -> FlowSets<T> {
        var result = original
        while true {
            result.iterations += 1;
            var changed = false
            for b in graph.order {
                var set: Set<T> = b == 0 ? [] : universe
                if b != 0 {
                    for p in graph.blocks[b].predecessors where graph.reachable.contains(p) {
                        set.formIntersection(result.output[p])
                    }
                };
                result.input[b] = set
                for i in graph.blocks[b].first...graph.blocks[b].last {
                    set = transfer(set, graph.instructions[i])
                };
                if set != result.output[b] {
                    changed = true
                };
                result.output[b] = set
            };
            if !changed {
                return result
            }
        }
    }
}

import Foundation
let passNames = ["constprop", "copyprop", "cse", "dce", "licm", "unreachable"], kinds = ["copy", "bin", "load", "store", "goto", "if", "param", "call", "return", "read", "print"]
func list(_ values: [String]) -> String {
    values.isEmpty ? "-" : values.joined(separator: ",")
}
func blockList(_ values: [Int]) -> String {
    list(values.map {
        "B\($0 + 1)"
    })
}
func numbers(_ values: [Int]) -> String {
    list(values.map {
        "#\($0 + 1)"
    })
}
func constant(_ instructions: [Instruction], _ definitions: Set<DefinitionKey>, _ variable: String) -> Int? {
    let numbers = definitions.filter {
        $0.variable == variable
    }.map(\.number);
    if numbers.isEmpty || numbers.contains(0) {
        return nil
    };
    var value: Int?
    for number in numbers {
        let instruction = instructions[number - 1];
        guard instruction.kind == "copy", let current = instruction.a?.constant else {
            return nil
        };
        if let value, value != current {
            return nil
        };
        value = current
    };
    return value
}
func propagate(_ function: inout Function, _ graph: Graph, _ analysis: Analysis, _ constants: Bool) -> (Int, [String]) {
    let instructions = graph.instructions;
    var replacements: [Int: [Instruction]] = [:], records: [String] = []
    for (i, original) in instructions.enumerated() where graph.reachable.contains(graph.owners[i]) {
        var instruction = original
        for field in 0..<2 {
            guard let operand = field == 0 ? instruction.a : instruction.b, let variable = operand.variable else {
                continue
            };
            let replacement: Operand?
            if constants {
                replacement = constant(instructions, analysis.beforeDefinitions[i], variable).map(Operand.constant)
            }
            else {
                replacement = analysis.beforeCopies[i].first {
                    $0.destination == variable
                }.map {
                    .variable($0.source)
                }
            }
            if let replacement {
                records.append("#\(i + 1): \(variable) -> \(replacement.text)");
                if field == 0 {
                    instruction.a = replacement
                } else {
                    instruction.b = replacement
                }
            }
        }
        if constants {
            switch Optimizations.fold(instruction) {
                case .deleted: records.append("#\(i + 1): delete \(instruction.text)");
                replacements[i] = [];
                continue;
                case .replacement(let folded): records.append("#\(i + 1): fold \(folded.text)");
                replacements[i] = [folded];
                continue;
                default: break
            }
        };
        replacements[i] = [instruction]
    };
    Optimizations.rewrite(&function, replacements);
    return (records.count, records)
}
func cse(_ function: inout Function, _ graph: Graph, _ analysis: Analysis) -> (Int, [String]) {
    let instructions = graph.instructions;
    var groups: [TacExpression: [Int]] = [:]
    for (i, instruction) in instructions.enumerated() where graph.reachable.contains(graph.owners[i]) {
        if let expression = instruction.expression, analysis.beforeExpressions[i].contains(expression) {
            groups[expression, default: []].append(i)
        }
    }
    var replacements: [Int: [Instruction]] = [:], records: [String] = [], count = 0
    for (expression, candidates) in groups.sorted(by: {
        $0.value[0] < $1.value[0]
    }) {
        var sources: Set<Int> = []
        for candidate in candidates {
            let block = graph.owners[candidate], first = graph.blocks[block].first
            if let source = (first..<candidate).reversed().first(where: {
                instructions[$0].expression == expression
            }) {
                sources.insert(source);
                continue
            }
            var pending = graph.blocks[block].predecessors.filter {
                graph.reachable.contains($0)
            }, seen: Set<Int> = []
            while let block = pending.popLast() {
                if !seen.insert(block).inserted {
                    continue
                }
                if let source = (graph.blocks[block].first...graph.blocks[block].last).reversed().first(where: {
                    instructions[$0].expression == expression
                }) {
                    sources.insert(source)
                }
                else {
                    pending += graph.blocks[block].predecessors.filter {
                        graph.reachable.contains($0)
                    }
                }
            }
        }
        sources.subtract(candidates);
        let temporary = Optimizations.temporary(&function)
        for source in sources {
            replacements[source] = Optimizations.cseRewrite(instructions[source], temporary, true)
        }
        for candidate in candidates {
            replacements[candidate] = Optimizations.cseRewrite(instructions[candidate], temporary, false)
        }
        records.append("\(expression.text): \(temporary) sources=\(numbers(sources.sorted())) replaced=\(numbers(candidates))");
        count += candidates.count
    };
    Optimizations.rewrite(&function, replacements);
    return (count, records)
}
func dce(_ function: inout Function, _ graph: Graph, _ analysis: Analysis) -> (Int, [String]) {
    var replacements: [Int: [Instruction]] = [:], records: [Int: String] = [:]
    for b in graph.reachable.sorted() {
        var live = analysis.live.output[b]
        for i in (graph.blocks[b].first...graph.blocks[b].last).reversed() {
            var instruction = graph.instructions[i]
            let selfCopy = instruction.kind == "copy" && instruction.destination == instruction.a?.variable, dead = ["copy", "bin", "load"].contains(instruction.kind) && instruction.destination.map {
                !live.contains($0)
            } ?? false
            if selfCopy || dead {
                replacements[i] = [];
                records[i] = "#\(i + 1): delete \(instruction.text)";
                continue
            }
            if instruction.kind == "call", let x = instruction.destination, !live.contains(x) {
                records[i] = "#\(i + 1): unused result \(instruction.text)";
                instruction.destination = nil;
                replacements[i] = [instruction]
            };
            live = Transfer.live(live, instruction)
        }
    };
    Optimizations.rewrite(&function, replacements);
    let lines = records.keys.sorted().map {
        records[$0]!
    };
    return (lines.count, lines)
}
func licm(_ function: inout Function, _ graph: Graph, _ analysis: Analysis) -> (Int, [String]) {
    let instructions = graph.instructions
    for loop in graph.loops.sorted(by: {
        ($0.blocks.count, $0.header) < ($1.blocks.count, $1.header)
    }) {
        func inside(_ number: Int) -> Bool {
            number != 0 && loop.blocks.contains(graph.owners[number - 1])
        }
        let indices = instructions.indices.filter {
            loop.blocks.contains(graph.owners[$0])
        };
        var marked: Set<Int> = [], order: [Int] = []
        while true {
            var changed = false
            for i in indices {
                let instruction = instructions[i]
                if marked.contains(i) || !["copy", "bin", "load"].contains(instruction.kind) {
                    continue
                }
                if instruction.kind == "load" && indices.contains(where: {
                    instructions[$0].kind == "call" || instructions[$0].kind == "store" && instructions[$0].array == instruction.array
                }) {
                    continue
                }
                let invariant = instruction.used.allSatisfy {
                    variable in let definitions = analysis.beforeDefinitions[i].filter {
                        $0.variable == variable
                    }.map(\.number);
                    return definitions.allSatisfy {
                        !inside($0)
                    } || definitions.count == 1 && inside(definitions[0]) && marked.contains(definitions[0] - 1)
                }
                if invariant {
                    marked.insert(i);
                    order.append(i);
                    changed = true
                }
            };
            if !changed {
                break
            }
        }
        var moved: [Int] = [], movedSet: Set<Int> = []
        for i in order {
            let instruction = instructions[i], destination = instruction.destination!
            if indices.filter({
                instructions[$0].destination == destination
            }).count != 1 || analysis.live.input[loop.header].contains(destination) {
                continue
            }
            let block = graph.owners[i], dominatesExits = loop.exits.allSatisfy {
                graph.dominators[$0].contains(block)
            }
            let dangerous = instruction.kind == "load" || instruction.kind == "bin" && ["/", "%"].contains(instruction.operation) && (instruction.b?.constant.map {
                $0 == 0
            } ?? true)
            let safe = !dangerous && loop.outside.allSatisfy {
                !analysis.live.input[$0].contains(destination)
            }
            if !dominatesExits && !safe {
                continue
            }
            if !instruction.used.allSatisfy({
                variable in analysis.beforeDefinitions[i].filter {
                    $0.variable == variable && inside($0.number)
                }.allSatisfy {
                    movedSet.contains($0.number - 1)
                }
            }) {
                continue
            }
            moved.append(i);
            movedSet.insert(i)
        }
        if !moved.isEmpty {
            let target = Optimizations.hoist(&function, graph, loop, moved);
            return (moved.count, ["B\(loop.header + 1): hoist \(numbers(moved)) to \(target)"])
        }
    };
    return (0, [])
}
func pass(_ name: String, _ function: inout Function) -> (Int, [String]) {
    let graph = Graph(function), analysis = Analysis(function, graph)
    switch name {
        case "constprop": return propagate(&function, graph, analysis, true);
        case "copyprop": return propagate(&function, graph, analysis, false);
        case "cse": return cse(&function, graph, analysis);
        case "dce": return dce(&function, graph, analysis);
        case "licm": return licm(&function, graph, analysis);
        default: let records = Optimizations.unreachable(&function, graph);
        return (records.count, records)
    }
}
func reach(_ start: Int, _ edges: [[Int]]) -> Set<Int> {
    var pending = [start], seen: Set<Int> = [];
    while let i = pending.popLast() {
        if seen.insert(i).inserted {
            pending += edges[i]
        }
    };
    return seen
}
struct Calls {
    let edges: [[Int]], reachable: Set<Int>
}
func callGraph(_ program: Program) -> Calls {
    let indices = Dictionary(uniqueKeysWithValues: program.functions.enumerated().map {
        ($0.element.name, $0.offset)
    }), edges = program.functions.map {
        function in Set(function.instructions.filter {
            $0.kind == "call"
        }.map {
            indices[$0.function]!
        }).sorted()
    };
    return Calls(edges: edges, reachable: reach(indices["main"]!, edges))
}
func graphReport(_ program: Program, _ graph: Calls, _ label: String) -> [String] {
    var lines = ["== call graph (\(label)) =="]
    for (i, function) in program.functions.enumerated() {
        let recursive = graph.edges[i].contains {
            reach($0, graph.edges).contains(i)
        };
        lines.append("\(function.name) -> \(list(graph.edges[i].map { program.functions[$0].name }))" + (recursive ? " (recursive)" : ""))
    }
    lines.append("unreachable functions: " + list(program.functions.indices.filter {
        !graph.reachable.contains($0)
    }.map {
        program.functions[$0].name
    }));
    return lines
}
func definitionList(_ set: Set<DefinitionKey>) -> String {
    list(set.sorted {
        ($0.number, $0.variable) < ($1.number, $1.variable)
    }.map {
        "\($0.variable):\($0.number)"
    })
}
func analysisReport(_ function: Function, _ label: String) -> [String] {
    let graph = Graph(function), analysis = Analysis(function, graph);
    var lines = ["== \(function.name) (\(label)) ==", "code:"], number = 0
    for line in function.code {
        switch line {
            case .label(let label): lines.append(label + ":")
            case .instruction(let instruction):
            var text = "  #\(number + 1) \(instruction.text)"
            if graph.reachable.contains(graph.owners[number]) {
                var used: Set<String> = [], chains: [String] = []
                for variable in instruction.used where used.insert(variable).inserted {
                    let definitions = analysis.beforeDefinitions[number].filter {
                        $0.variable == variable
                    }.map(\.number).sorted();
                    chains.append(variable + ":" + list(definitions.map(String.init)))
                }
                if !chains.isEmpty {
                    text += " | " + chains.joined(separator: " ")
                }
            };
            lines.append(text);
            number += 1
        }
    }
    lines.append("blocks: \(graph.blocks.count)")
    for (b, block) in graph.blocks.enumerated() {
        lines.append("B\(b + 1) \(block.first + 1)-\(block.last + 1) labels=\(list(block.labels)) preds=\(blockList(block.predecessors)) succs=\(blockList(block.successors))")
    }
    lines += ["unreachable: " + blockList(graph.blocks.indices.filter {
        !graph.reachable.contains($0)
    }), "order: " + blockList(graph.order), "dominators:"]
    for b in graph.reachable.sorted() {
        lines.append("B\(b + 1) idom=\(graph.idom[b].map { "B\($0 + 1)" } ?? "-") dom=\(blockList(graph.dominators[b].sorted()))")
    };
    lines.append("dominator tree:")
    func tree(_ block: Int, _ depth: Int) {
        lines.append(String(repeating: " ", count: depth * 2) + "B\(block + 1)");
        for b in graph.blocks.indices where graph.idom[b] == block {
            tree(b, depth + 1)
        }
    };
    tree(0, 0)
    lines.append("loops: \(graph.loops.count)")
    for loop in graph.loops {
        lines.append("header=B\(loop.header + 1) latches=\(blockList(loop.latches)) depth=\(loop.depth) blocks=\(blockList(loop.blocks.sorted())) exits=\(blockList(loop.exits.sorted()))")
    }
    lines.append("reaching definitions: iterations=\(analysis.definitions.iterations)")
    for b in graph.reachable.sorted() {
        lines.append("B\(b + 1) in=\(definitionList(analysis.definitions.input[b])) out=\(definitionList(analysis.definitions.output[b]))")
    };
    lines.append("liveness: iterations=\(analysis.live.iterations)")
    for b in graph.reachable.sorted() {
